import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"DataClassification in AL","description":"","frontmatter":{},"headers":[],"relativePath":"tables-fields-and-business-data/dataclassification.md","filePath":"tables-fields-and-business-data/dataclassification.md"}`),a={name:`tables-fields-and-business-data/dataclassification.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="dataclassification-in-al" tabindex="-1">DataClassification in AL <a class="header-anchor" href="#dataclassification-in-al" aria-label="Permalink to “DataClassification in AL”">​</a></h1><p>We&#39;ve been adding this property to almost every field in our tables:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DataClassification = CustomerContent;</span></span></code></pre></div><p>But what does it actually do? And why does Business Central care about how we classify our data?</p><p>Let&#39;s break it down.</p><h2 id="what-is-dataclassification" tabindex="-1">What is <code>DataClassification</code>? <a class="header-anchor" href="#what-is-dataclassification" aria-label="Permalink to “What is DataClassification?”">​</a></h2><p><code>DataClassification</code> is an AL property that describes the type of data a table or field contains.</p><p>It helps organizations understand what kind of information their Business Central application stores, supporting data governance, privacy assessments, and compliance activities.</p><p>For example, consider our <code>Course</code> table:</p><table tabindex="0"><thead><tr><th>Field</th><th>Example value</th><th>Data classification</th></tr></thead><tbody><tr><td>Course Code</td><td>CS101</td><td><code>CustomerContent</code></td></tr><tr><td>Course Name</td><td>Introduction to Programming</td><td><code>CustomerContent</code></td></tr><tr><td>Description</td><td>Learn programming fundamentals</td><td><code>CustomerContent</code></td></tr><tr><td>Price</td><td>1500</td><td><code>CustomerContent</code></td></tr></tbody></table><p>These fields contain information created or maintained by the organization using Business Central, so <code>CustomerContent</code> is a reasonable classification.</p><p><strong>Important:</strong> <code>DataClassification</code> does not encrypt data, control who can access it, or automatically make the application compliant with privacy regulations. It describes the nature of the data.</p><h2 id="common-data-classifications" tabindex="-1">Common data classifications <a class="header-anchor" href="#common-data-classifications" aria-label="Permalink to “Common data classifications”">​</a></h2><p>Here are several classifications worth knowing.</p><table tabindex="0"><thead><tr><th>Classification</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>CustomerContent</code></td><td>Content created or maintained by the Business Central customer organization</td><td>Course descriptions, product details</td></tr><tr><td><code>EndUserIdentifiableInformation</code></td><td>Information that can identify an individual end user</td><td>A person&#39;s name or email address</td></tr><tr><td><code>EndUserPseudonymousIdentifiers</code></td><td>Identifiers associated with a user that don&#39;t directly reveal their identity</td><td>A pseudonymous user identifier</td></tr><tr><td><code>AccountData</code></td><td>Data associated with an account</td><td>Account-related information</td></tr><tr><td><code>OrganizationIdentifiableInformation</code></td><td>Information that identifies an organization</td><td>An organization&#39;s name or identifying details</td></tr><tr><td><code>SystemMetadata</code></td><td>Technical or operational metadata about the system</td><td>System-generated metadata</td></tr><tr><td><code>ToBeClassified</code></td><td>Data whose classification hasn&#39;t yet been determined</td><td>A field awaiting review</td></tr></tbody></table><p>These are examples, not an exhaustive list. Choose the classification that best reflects the information being stored, rather than automatically assigning the same value to every field.</p><p>You can find the complete list in Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-dataclassification-property" target="_blank" rel="noreferrer">DataClassification property documentation</a>.</p><h2 id="how-do-we-use-it-in-al" tabindex="-1">How do we use it in AL? <a class="header-anchor" href="#how-do-we-use-it-in-al" aria-label="Permalink to “How do we use it in AL?”">​</a></h2><p>Let&#39;s look at our existing <code>Course</code> table:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>table 50102 Course</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Course&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(1; &quot;Course Code&quot;; Code[20])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Code&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(2; &quot;Course Name&quot;; Text[100])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Course Name&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(3; Description; Text[250])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Description&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        field(4; Price; Decimal)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Course Code&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Notice that <code>DataClassification</code> appears twice at different levels:</p><ul><li><strong>At the table level:</strong> Provides a classification for the table.</li><li><strong>At the field level:</strong> Classifies the individual field.</li></ul><p>Classifying fields individually is particularly useful because a single table can contain different types of information.</p><p>For example, an <code>Enrollment</code> table might contain a course code, a student&#39;s name, and an internal processing identifier. Those fields might warrant different classifications.</p><h2 id="is-dataclassification-mandatory" tabindex="-1">Is <code>DataClassification</code> mandatory? <a class="header-anchor" href="#is-dataclassification-mandatory" aria-label="Permalink to “Is DataClassification mandatory?”">​</a></h2><p>Business Central allows you to define tables and fields without explicitly specifying this property, but leaving data unclassified is generally poor practice.</p><p>For our learning project, <strong>continue specifying <code>DataClassification</code> explicitly on the table and its fields</strong>.</p><p>That gives us a consistent habit and makes our intentions clear when someone reviews the code.</p><h2 id="does-it-change-how-the-application-behaves" tabindex="-1">Does it change how the application behaves? <a class="header-anchor" href="#does-it-change-how-the-application-behaves" aria-label="Permalink to “Does it change how the application behaves?”">​</a></h2><p>Not in the way a validation rule or permission does.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>field(4; Price; Decimal)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    Caption = &#39;Price&#39;;</span></span>
<span class="line"><span>    DataClassification = CustomerContent;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This does not prevent unauthorized users from seeing the price. Access control must be handled separately.</p><p>Likewise, classifying a field as <code>EndUserIdentifiableInformation</code> does not automatically anonymize its contents.</p><p>Think of <code>DataClassification</code> as a <strong>label describing the data</strong>, not a mechanism enforcing security.</p><h3 id="official-documentation" tabindex="-1">Official documentation <a class="header-anchor" href="#official-documentation" aria-label="Permalink to “Official documentation”">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-dataclassification-property" target="_blank" rel="noreferrer">DataClassification property — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/admin-classifying-data-sensitivity" target="_blank" rel="noreferrer">Data classification in Business Central — Microsoft Learn</a></li></ul>`,37)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};